	case resourceClaimTemplateResourceV1Beta1:
		// Decode as v1beta1
		obj = &resourcev1beta1.ResourceClaimTemplate{}
	case resourceClaimTemplateResourceV1Beta2:
		// Decode as v1beta2
		obj = &resourcev1beta2.ResourceClaimTemplate{}
	default:
